// Selected renderers from amtiYo/agents at 61a84130828268b1a9a2761d1565caed6394b039.
// Apache-2.0. Changes: inline the structural input type and omit unrelated renderers.
interface ResolvedMcpServer { name: string; transport: 'stdio' | 'http' | 'sse'; command?: string; args?: string[]; cwd?: string; url?: string; env?: Record<string,string>; headers?: Record<string,string>; bearerTokenEnvVar?: string; connectTimeout?: number; timeout?: number }


function escapeToml(value: string): string {
  return value.replaceAll('\\', '\\\\').replaceAll('"', '\\"')
}

function quoteTomlKey(key: string): string {
  return `"${escapeToml(key)}"`
}

export interface RenderResult {
  content: string
  warnings: string[]
}

export interface TomlRenderOptions {
  /** Sub-table used for HTTP headers: Codex calls it `http_headers`, Grok calls it `headers`. */
  headersTable: string
  /** Emit `type = "sse"` for legacy SSE servers (Grok) instead of a plain url (Codex). */
  emitSseType: boolean
  label: string
}

const CODEX_TOML_OPTIONS: TomlRenderOptions = {
  headersTable: 'http_headers',
  emitSseType: false,
  label: 'Codex'
}

const GROK_TOML_OPTIONS: TomlRenderOptions = {
  headersTable: 'headers',
  emitSseType: true,
  label: 'Grok'
}

/**
 * Render MCP servers into the `[mcp_servers.*]` TOML dialect shared by Codex and Grok Build.
 *
 * @param servers - Resolved MCP servers
 * @param options - Dialect differences between the two tools
 */
export function renderMcpToml(servers: ResolvedMcpServer[], options: TomlRenderOptions): RenderResult {
  const warnings: string[] = []
  const lines: string[] = ['# Generated by agents sync. Do not edit manually.', '']

  for (const server of servers) {
    lines.push(`[mcp_servers.${quoteTomlKey(server.name)}]`)

    if (server.transport === 'stdio') {
      if (!server.command) {
        warnings.push(`Server "${server.name}" has no command; skipped in ${options.label} output.`)
        lines.pop()
        continue
      }
      lines.push(`command = "${escapeToml(server.command)}"`)
      lines.push(
        `args = [${(server.args ?? []).map((arg) => `"${escapeToml(arg)}"`).join(', ')}]`,
      )
      if (server.cwd) {
        lines.push(`cwd = "${escapeToml(server.cwd)}"`)
      }
    } else {
      if (!server.url) {
        warnings.push(`Server "${server.name}" has no url; skipped in ${options.label} output.`)
        lines.pop()
        continue
      }
      lines.push(`url = "${escapeToml(server.url)}"`)
      if (server.transport === 'sse') {
        if (options.emitSseType) {
          lines.push('type = "sse"')
        } else {
          warnings.push(
            `Server "${server.name}" uses the deprecated sse transport; rendering as URL for ${options.label} compatibility.`,
          )
        }
      }
      if (server.bearerTokenEnvVar) {
        lines.push(`bearer_token_env_var = "${escapeToml(server.bearerTokenEnvVar)}"`)
      }
    }

    lines.push('enabled = true')
    if (typeof server.connectTimeout === 'number') {
      lines.push(`startup_timeout_sec = ${String(Math.max(1, Math.round(server.connectTimeout / 1000)))}`)
    }
    if (typeof server.timeout === 'number') {
      lines.push(`tool_timeout_sec = ${String(Math.max(1, Math.round(server.timeout / 1000)))}`)
    }
    lines.push('')

    if (server.env && Object.keys(server.env).length > 0) {
      lines.push(`[mcp_servers.${quoteTomlKey(server.name)}.env]`)
      for (const key of Object.keys(server.env).sort()) {
        lines.push(`${quoteTomlKey(key)} = "${escapeToml(server.env[key])}"`)
      }
      lines.push('')
    }

    if (server.headers && Object.keys(server.headers).length > 0) {
      lines.push(`[mcp_servers.${quoteTomlKey(server.name)}.${options.headersTable}]`)
      for (const key of Object.keys(server.headers).sort()) {
        lines.push(`${quoteTomlKey(key)} = "${escapeToml(server.headers[key])}"`)
      }
      lines.push('')
    }
  }

  return {
    content: `${lines.join('\n')}\n`,
    warnings
  }
}

/** Render MCP servers for Codex, whose headers live in an `http_headers` table. */
export function renderCodexToml(servers: ResolvedMcpServer[]): RenderResult {
  return renderMcpToml(servers, CODEX_TOML_OPTIONS)
}

/** Render MCP servers for Grok Build, which uses a plain `headers` table and marks sse. */
export function renderGrokToml(servers: ResolvedMcpServer[]): RenderResult {
  return renderMcpToml(servers, GROK_TOML_OPTIONS)
}

export function renderGeminiServers(servers: ResolvedMcpServer[]): {
  mcpServers: Record<string, unknown>
  warnings: string[]
} {
  const warnings: string[] = []
  const out: Record<string, unknown> = {}

  for (const server of servers) {
    if (server.transport === 'stdio') {
      if (!server.command) {
        warnings.push(`Server "${server.name}" has no command; skipped in Gemini output.`)
        continue
      }
      out[server.name] = {
        type: 'stdio',
        command: server.command,
        args: server.args ?? [],
        ...(server.cwd ? { cwd: server.cwd } : {}),
        ...(server.env ? { env: server.env } : {})
      }
      continue
    }

    if (!server.url) {
      warnings.push(`Server "${server.name}" has no url; skipped in Gemini output.`)
      continue
    }
    out[server.name] = {
      ...(server.transport === 'http'
        ? { httpUrl: server.url }
        : { url: server.url }),
      ...(server.headers ? { headers: server.headers } : {})
    }
  }

  return { mcpServers: out, warnings }
}

